function [fitresult, gof] = logisticFit(y, x, plotFlag)
%CREATEFIT(COEFVALS)
%  Create a fit.
%
%  Data for 'singleExp' fit:
%      Y Output: coefVals
%  Output:
%      fitresult : a fit object representing the fit.
%      gof : structure with goodness-of fit info.
%
%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 05-Oct-2016 10:03:20

if nargin < 3
    plotFlag = 0;
end

if nargin < 2
    x = [];
end

%% Fit: 'singleExp'.
[xData, yData] = prepareCurveData( x, y );

% Set up fittype and options.
ft = fittype( '(a/(1 + exp(-b*(x-c)))) - d', 'independent', 'x', 'dependent', 'y' );
opts = fitoptions( 'Method', 'NonlinearLeastSquares' );
opts.Display = 'Off';
opts.StartPoint = [0.6 0.8 7.8 -1];

% Fit model to data.
[fitresult, gof] = fit( xData, yData, ft, opts );

% Plot fit with data.
if plotFlag == 1
    figure( 'Name', 'singleExp' );
    h = plot( fitresult, xData, yData );
    legend( h, 'coefVals', 'singleExp', 'Location', 'NorthEast' );
    % Label axes
    ylabel coefVals
    grid on
end

